  const documentBlocks = (request.documents ?? []).map((document, index) => [
    `--- BEGIN UNTRUSTED DOCUMENT ${index + 1}: ${document.name} ---`,
    document.text,
    `--- END UNTRUSTED DOCUMENT ${index + 1} ---`,
  ].join('\n'));
  const message = [
